let createdEmployeeList = [];

try {
    const storedEmployees =
        pm.collectionVariables.get("createdEmployees");

    if (storedEmployees) {
        createdEmployeeList = JSON.parse(storedEmployees);
    }
} catch (error) {
    console.log("Invalid createdEmployees value. Resetting to []");
    createdEmployeeList = [];
}

let responseData = {};
    try {
        responseData = pm.response.json();
    } catch (e) {
        responseData = {};
    }

function setcreatedEmployeesToNull() {
     pm.collectionVariables.set("createdEmployees", []);
}

pm.test("Successful response status", function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 201, 400]);
});

pm.test("Store employee number", function () {

    if (responseData.data && responseData.data.empNumber) {

        setcreatedEmployeesToNull();

        createdEmployeeList.push({
            empID: responseData.data.employeeId,
            empNumber: responseData.data.empNumber
        });

        pm.collectionVariables.set(
            "createdEmployees",
            JSON.stringify(createdEmployeeList)
        );

        console.log("Created list before passing to test :", pm.collectionVariables.get("createdEmployees"));

        pm.expect(responseData.data).to.have.property("empNumber");

    } else {

        pm.expect(pm.response.code).to.be.oneOf([400, 422, 500]);

    }
});

const createdEmployees = JSON.parse(
    pm.collectionVariables.get("createdEmployees") || "[]"
);

console.log("created employees :", createdEmployees);

const employeeIDforTestEMp = pm.iterationData.get("employeeId");

const selectedEmployee = createdEmployees.find(
    emp => String(emp.empID) === String(employeeIDforTestEMp)
);

pm.test("Employee found in created employees", function () {
    pm.expect(selectedEmployee).to.not.be.undefined;
});

if (selectedEmployee) {
    pm.collectionVariables.set("emp_number", selectedEmployee.empNumber);
    console.log("emp_number:", selectedEmployee.empNumber);
}

